package com.trampolim.api.communication;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.MediaType;
import com.trampolim.api.BackendApplication;
import com.trampolim.api.security.TrailTokenService;
import com.trampolim.api.company.RecruitmentService;
import com.trampolim.api.education.QuestionService;
import com.trampolim.api.education.LearningNotifications;
@SpringBootTest(classes=BackendApplication.class)
class CommunicationPostgresTest {
 @Autowired @Qualifier("jdbcTemplate")JdbcTemplate opp;
 @Autowired @Qualifier("empresasJdbcTemplate")JdbcTemplate companies;
 @Autowired @Qualifier("capacitaJdbcTemplate")JdbcTemplate learning;
 @Autowired @Qualifier("opportunitiesCommunications")CommunicationStore opportunities;
 @Autowired @Qualifier("companyCommunications")CommunicationStore corporate;
 @Autowired @Qualifier("learningCommunications")CommunicationStore education;
 @Autowired WebApplicationContext context;@Autowired TrailTokenService tokens;@Autowired RecruitmentService recruitment;@Autowired QuestionService questions;@Autowired LearningNotifications legacy;
 record User(long id,String email){}
 User user(JdbcTemplate db,String trail){return user(db,trail,UUID.randomUUID()+"@example.test");}
 User user(JdbcTemplate db,String trail,String email){String sql=trail.equals("OPORTUNIDADES")?"INSERT INTO app_users(email,password_hash,full_name,email_verified,account_type) VALUES (?,'synthetic','Fixture',TRUE,'PERSON') RETURNING id":trail.equals("EMPRESAS")?"INSERT INTO company_users(email,password_hash,full_name,email_verified,account_status) VALUES (?,'synthetic','Fixture',TRUE,'ACTIVE') RETURNING id":"INSERT INTO student_users(email,password_hash,full_name,education_stage,email_verified,account_status,terms_accepted_at) VALUES (?,'synthetic','Fixture','HIGH_SCHOOL',TRUE,'ACTIVE',CURRENT_TIMESTAMP) RETURNING id";return new User(db.queryForObject(sql,Long.class,email),email);}
 long job(){return opp.queryForObject("INSERT INTO catalog_items(kind,title,provider,description,url,area,location,modality,active,moderation_status) VALUES ('job','Vaga sintética','Fonte de teste','Fixture','https://example.test','technology','Irecê','Remoto',TRUE,'APPROVED') RETURNING id",Long.class);}
 long application(User u){return opp.queryForObject("INSERT INTO job_applications(user_id,item_id) VALUES (?,?) RETURNING id",Long.class,u.id(),job());}
 void changeStage(long application,String status){opp.update("UPDATE job_applications SET status=? WHERE id=?",status,application);}
 void fanout(CommunicationStore store){for(int i=0;i<20;i++)store.pumpSources();}
 void work(CommunicationStore store){fanout(store);store.pumpDeliveries();}
 long count(JdbcTemplate db,User u,String state){return db.queryForObject("SELECT count(*) FROM communication_deliveries WHERE user_id=? AND status=?",Long.class,u.id(),state);}
 void code(int expected,Runnable action){assertEquals(expected,assertThrows(ResponseStatusException.class,action::run).getStatusCode().value());}
 CommunicationStore.Preferences prefs(boolean enabled,int daily,int minutes,Map<String,Boolean> kinds,long revision){return new CommunicationStore.Preferences(enabled,daily,minutes,kinds,revision);}
 record Course(User teacher,long id,long module,long lesson){}
 Course course(){var teacher=user(learning,"CAPACITA");learning.update("INSERT INTO learning_account_roles(user_id,role) VALUES (?,'TEACHER')",teacher.id());long c=learning.queryForObject("INSERT INTO learning_courses(teacher_id,title,description,category,status) VALUES (?,'Curso sintético','Fixture','Teste','PUBLISHED') RETURNING id",Long.class,teacher.id());long subject=learning.queryForObject("INSERT INTO learning_subjects(course_id,title) VALUES (?,'Assunto') RETURNING id",Long.class,c);long module=learning.queryForObject("INSERT INTO learning_modules(subject_id,title) VALUES (?,'Módulo') RETURNING id",Long.class,subject);long lesson=learning.queryForObject("INSERT INTO learning_lessons(module_id,title,status,media_key,duration_seconds,validation_status) VALUES (?,'Videoaula sintética','PUBLISHED',?,180,'READY') RETURNING id",Long.class,module,UUID.randomUUID());return new Course(teacher,c,module,lesson);}
 void study(User student,Course course){learning.update("INSERT INTO learning_lesson_progress(student_id,lesson_id) VALUES (?,?)",student.id(),course.lesson());}
 @Test void applicationChangesArePersistentIdempotentAndOwned(){var u=user(opp,"OPORTUNIDADES");long id=application(u);changeStage(id,"APPLIED");changeStage(id,"APPLIED");work(opportunities);assertEquals(1,count(opp,u,"DELIVERED"));work(opportunities);assertEquals(1,count(opp,u,"DELIVERED"));var rows=(List<?>)opportunities.history(u.email(),Long.MAX_VALUE,20,false).get("items");var other=user(opp,"OPORTUNIDADES");long notice=((Number)((Map<?,?>)rows.getFirst()).get("id")).longValue();code(404,()->opportunities.read(other.email(),notice));opportunities.read(u.email(),notice);opportunities.read(u.email(),notice);assertEquals(0L,opportunities.history(u.email(),Long.MAX_VALUE,20,false).get("unreadCount"));}
 @Test void newJobsReuseOptedInFiltersAndPublicationDeduplication(){var u=user(opp,"OPORTUNIDADES");opp.update("UPDATE app_users SET alert_preferences=? WHERE id=?","{\"enabled\":true,\"frequency\":\"immediate\",\"areas\":[\"technology\"],\"city\":\"Irecê\",\"modality\":\"Remoto\"}",u.id());long id=job();work(opportunities);assertEquals(1,count(opp,u,"DELIVERED"));opp.update("UPDATE catalog_items SET active=FALSE WHERE id=?",id);opp.update("UPDATE catalog_items SET active=TRUE WHERE id=?",id);work(opportunities);assertEquals(1,count(opp,u,"DELIVERED"));opp.update("UPDATE app_users SET alert_preferences=? WHERE id=?","{\"enabled\":false,\"areas\":[\"technology\"]}",u.id());job();work(opportunities);assertEquals(1,count(opp,u,"DELIVERED"));}
 @Test void preferenceRevisionOptOutAndInputLimitsAreEnforced(){var u=user(opp,"OPORTUNIDADES");long id=application(u);changeStage(id,"APPLIED");fanout(opportunities);opportunities.save(u.email(),prefs(false,2,0,Map.of(),0));opportunities.pumpDeliveries();assertEquals(1,count(opp,u,"SUPPRESSED"));assertEquals(0,count(opp,u,"DELIVERED"));code(409,()->opportunities.save(u.email(),prefs(true,2,0,Map.of(),0)));code(400,()->opportunities.save(u.email(),prefs(true,0,0,Map.of(),1)));code(400,()->opportunities.save(u.email(),prefs(true,2,0,Map.of("WHATSAPP",true),1)));code(400,()->opportunities.history(u.email(),Long.MAX_VALUE,51,true));}
 @Test void frequencyAndDailyLimitsDeferWithoutCountingAFalseDelivery(){var u=user(opp,"OPORTUNIDADES");opportunities.save(u.email(),prefs(true,100,60,Map.of(),0));long id=application(u);changeStage(id,"APPLIED");changeStage(id,"INTERVIEW");work(opportunities);assertEquals(1,count(opp,u,"DELIVERED"));assertEquals(1,count(opp,u,"PENDING"));assertEquals("FREQUENCY_LIMIT",opp.queryForObject("SELECT reason FROM communication_deliveries WHERE user_id=? AND status='PENDING'",String.class,u.id()));opportunities.save(u.email(),prefs(true,100,0,Map.of(),1));opp.update("UPDATE communication_deliveries SET next_attempt_at=CURRENT_TIMESTAMP WHERE user_id=?",u.id());opportunities.pumpDeliveries();assertEquals(2,count(opp,u,"DELIVERED"));var daily=user(opp,"OPORTUNIDADES");opportunities.save(daily.email(),prefs(true,1,0,Map.of(),0));long a=application(daily);changeStage(a,"APPLIED");changeStage(a,"INTERVIEW");work(opportunities);assertEquals(1,count(opp,daily,"DELIVERED"));assertEquals("DAILY_LIMIT",opp.queryForObject("SELECT reason FROM communication_deliveries WHERE user_id=? AND status='PENDING'",String.class,daily.id()));}
 @Test void concurrentWorkersPersistOnlyOneDelivery()throws Exception{var u=user(opp,"OPORTUNIDADES");long id=application(u);changeStage(id,"APPLIED");fanout(opportunities);try(var pool=Executors.newFixedThreadPool(4)){var jobs=new ArrayList<Future<?>>();for(int i=0;i<8;i++)jobs.add(pool.submit(opportunities::pumpDeliveries));for(var f:jobs)f.get(20,TimeUnit.SECONDS);}assertEquals(1,count(opp,u,"DELIVERED"));assertEquals(1,opp.queryForObject("SELECT attempts FROM communication_deliveries WHERE user_id=?",Integer.class,u.id()));}
 @Test void persistenceFailuresBackOffAndStopAtFiveAttempts(){var u=user(opp,"OPORTUNIDADES");long id=application(u);changeStage(id,"APPLIED");fanout(opportunities);String suffix=u.id()+"";opp.execute("CREATE FUNCTION comm_test_failure_"+suffix+"() RETURNS trigger AS $$ BEGIN IF NEW.user_id="+u.id()+" AND NEW.status='DELIVERED' THEN RAISE EXCEPTION 'synthetic failure'; END IF; RETURN NEW; END $$ LANGUAGE plpgsql");opp.execute("CREATE TRIGGER comm_test_failure_"+suffix+" BEFORE UPDATE ON communication_deliveries FOR EACH ROW EXECUTE FUNCTION comm_test_failure_"+suffix+"()");try{for(int i=0;i<5;i++){opp.update("UPDATE communication_deliveries SET next_attempt_at=CURRENT_TIMESTAMP WHERE user_id=?",u.id());opportunities.pumpDeliveries();}assertEquals(1,count(opp,u,"FAILED"));assertEquals(0,count(opp,u,"DELIVERED"));assertEquals(5,opp.queryForObject("SELECT attempts FROM communication_deliveries WHERE user_id=?",Integer.class,u.id()));assertEquals("PERSISTENCE_ERROR",opp.queryForObject("SELECT reason FROM communication_deliveries WHERE user_id=?",String.class,u.id()));opportunities.pumpDeliveries();assertEquals(5,opp.queryForObject("SELECT attempts FROM communication_deliveries WHERE user_id=?",Integer.class,u.id()));}finally{opp.execute("DROP TRIGGER comm_test_failure_"+suffix+" ON communication_deliveries");opp.execute("DROP FUNCTION comm_test_failure_"+suffix+"()");}}
 @Test void courseChangesNotifyOnlyActualParticipantsAndIgnoreNoOpUpdates(){var c=course();var student=user(learning,"CAPACITA");var outsider=user(learning,"CAPACITA");study(student,c);learning.update("UPDATE learning_courses SET description='Conteúdo revisado' WHERE id=?",c.id());learning.update("UPDATE learning_courses SET description='Conteúdo revisado' WHERE id=?",c.id());work(education);assertEquals(1,count(learning,student,"DELIVERED"));assertEquals(0,count(learning,outsider,"DELIVERED"));assertEquals("COURSE_CHANGED",learning.queryForObject("SELECT kind FROM communication_deliveries WHERE user_id=?",String.class,student.id()));}
 @Test void unavailableAssessmentIsNotAdvertisedAsDelivered(){var c=course();var student=user(learning,"CAPACITA");study(student,c);long assessment=learning.queryForObject("INSERT INTO learning_assessments(course_id,title,draft) VALUES (?,'Avaliação sintética','{}'::jsonb) RETURNING id",Long.class,c.id());long version=learning.queryForObject("INSERT INTO learning_assessment_versions(assessment_id,version_number,definition) VALUES (?,1,'{}'::jsonb) RETURNING id",Long.class,assessment);learning.update("UPDATE learning_assessments SET current_version_id=?,status='PUBLISHED' WHERE id=?",version,assessment);fanout(education);learning.update("UPDATE learning_assessments SET status='HIDDEN' WHERE id=?",assessment);education.pumpDeliveries();assertEquals(1,count(learning,student,"SUPPRESSED"));assertEquals(0,count(learning,student,"DELIVERED"));}
 @Test void questionRepliesRespectOptOutAndKeepExistingSseProjectionAndReadState(){var c=course();var student=user(learning,"CAPACITA");education.save(student.email(),prefs(true,100,0,Map.of("QUESTION_REPLY",false),0));long q=((Number)questions.create(student.email(),new QuestionService.QuestionInput(UUID.randomUUID(),c.id(),c.module(),c.lesson(),"Dúvida sintética","Texto de teste",null,"","")).get("id")).longValue();questions.send(c.teacher().email(),q,new QuestionService.MessageInput(UUID.randomUUID(),"Resposta preservada no mural",null,"",""),true);assertEquals(1,count(learning,student,"SUPPRESSED"));assertEquals(0,learning.queryForObject("SELECT count(*) FROM learning_notifications WHERE user_id=?",Integer.class,student.id()));education.save(student.email(),prefs(true,100,0,Map.of("QUESTION_REPLY",true),1));questions.send(c.teacher().email(),q,new QuestionService.MessageInput(UUID.randomUUID(),"Nova resposta",null,"",""),true);assertEquals(1,count(learning,student,"DELIVERED"));long legacyId=learning.queryForObject("SELECT legacy_id FROM communication_deliveries WHERE user_id=? AND status='DELIVERED'",Long.class,student.id());legacy.read(student.email(),legacyId);assertEquals(0L,education.history(student.email(),Long.MAX_VALUE,20,false).get("unreadCount"));}
 @Test void corporateEventsStayWithAuthorizedCompanyAndNeverMatchAccountsByEmail(){var owner=user(companies,"EMPRESAS");var candidate=user(opp,"OPORTUNIDADES");var outsider=user(companies,"EMPRESAS");String cnpj=String.format("%014d",Math.abs(UUID.randomUUID().getLeastSignificantBits()%100000000000000L));long company=companies.queryForObject("INSERT INTO companies(owner_user_id,legal_name,trade_name,cnpj,phone,industry,address,city,state,verification_status) VALUES (?,'Fixture','Fixture',?,'teste','teste','teste','Irecê','BA','APPROVED') RETURNING id",Long.class,owner.id(),cnpj);long listing=companies.queryForObject("INSERT INTO company_listings(company_id,kind,title,area,description,requirements,location,modality,url,contact_email) VALUES (?,'job','Fixture','teste','teste','teste','Irecê','Remoto','https://example.test','fixture@example.test') RETURNING id",Long.class,company);long application=companies.queryForObject("INSERT INTO company_applications(listing_id,candidate_name,candidate_email) VALUES (?,'Pessoa sintética',?) RETURNING id",Long.class,listing,candidate.email());recruitment.change(owner.email(),application,new RecruitmentService.Change("INTERVIEW",0L,UUID.randomUUID(),false));work(corporate);assertEquals(1,count(companies,owner,"DELIVERED"));assertEquals(0,count(companies,outsider,"DELIVERED"));assertEquals(0,count(opp,candidate,"DELIVERED"));companies.update("INSERT INTO company_selection_outcomes(id,application_id,interview_at,request_key,request_hash) VALUES (?,?,CURRENT_TIMESTAMP+INTERVAL '1 day',?,?)",UUID.randomUUID(),application,UUID.randomUUID(),"0".repeat(64));work(corporate);assertEquals(2,count(companies,owner,"DELIVERED"));assertEquals(0,count(opp,candidate,"DELIVERED"));}
 @Test void endpointsRejectCrossTrailTokensEvenForTheSameEmail()throws Exception{String email=UUID.randomUUID()+"@example.test";var people=List.of(user(opp,"OPORTUNIDADES",email),user(companies,"EMPRESAS",email),user(learning,"CAPACITA",email));var trails=TrailTokenService.Trail.values();var paths=List.of("/api/communications","/api/empresas/communications","/api/capacita/communications");var mvc=MockMvcBuilders.webAppContextSetup(context).apply(SecurityMockMvcConfigurers.springSecurity()).build();for(int i=0;i<3;i++){var expected=TrailTokenService.Trail.valueOf(List.of("OPORTUNIDADES","EMPRESAS","CAPACITA").get(i));var token=tokens.issue(expected,email,people.get(i).id(),0);mvc.perform(get(paths.get(i)+"/preferences").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$.channels.EMAIL").value("NOT_ACTIVATED"));mvc.perform(put(paths.get(i)+"/preferences").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"enabled\":false,\"dailyLimit\":10,\"minimumIntervalMinutes\":0,\"categories\":{},\"expectedRevision\":0}")).andExpect(status().isOk());for(var wrong:trails)if(wrong!=expected){String wrongToken=tokens.issue(wrong,email,people.get(i).id(),0);int status=mvc.perform(get(paths.get(i)).header("Authorization","Bearer "+wrongToken)).andReturn().getResponse().getStatus();assertTrue(Set.of(401,403).contains(status));}}}
 @Test void unavailableAccountsAndExpiredItemsAreSuppressedAndRetentionDoesNotResetPreferences(){var u=user(opp,"OPORTUNIDADES");long app=application(u);changeStage(app,"APPLIED");fanout(opportunities);opp.update("UPDATE app_users SET email_verified=FALSE WHERE id=?",u.id());opportunities.pumpDeliveries();assertEquals(1,count(opp,u,"SUPPRESSED"));code(403,()->opportunities.preferences(u.email()));opp.update("UPDATE app_users SET email_verified=TRUE WHERE id=?",u.id());long other=application(u);changeStage(other,"APPLIED");fanout(opportunities);opp.update("UPDATE communication_deliveries SET created_at=CURRENT_TIMESTAMP-INTERVAL '31 days' WHERE user_id=? AND status='PENDING'",u.id());opportunities.pumpDeliveries();assertEquals(2,count(opp,u,"SUPPRESSED"));opportunities.save(u.email(),prefs(false,1,0,Map.of(),0));opp.update("UPDATE communication_deliveries SET created_at=CURRENT_TIMESTAMP-INTERVAL '91 days' WHERE user_id=?",u.id());opportunities.retain();assertEquals(0,count(opp,u,"SUPPRESSED"));assertEquals(false,opportunities.preferences(u.email()).get("enabled"));}

 @Test void publishedAssessmentUsesTheCurrentVersionAndActualCourseParticipants(){var c=course();var student=user(learning,"CAPACITA");var outsider=user(learning,"CAPACITA");study(student,c);long a=learning.queryForObject("INSERT INTO learning_assessments(course_id,title,draft) VALUES (?,'Avaliação sintética','{}'::jsonb) RETURNING id",Long.class,c.id());long version=learning.queryForObject("INSERT INTO learning_assessment_versions(assessment_id,version_number,definition) VALUES (?,1,'{}'::jsonb) RETURNING id",Long.class,a);learning.update("UPDATE learning_assessments SET current_version_id=?,status='PUBLISHED' WHERE id=?",version,a);work(education);assertEquals(1,count(learning,student,"DELIVERED"));assertEquals(0,count(learning,outsider,"DELIVERED"));assertEquals("ASSESSMENT_AVAILABLE",learning.queryForObject("SELECT kind FROM communication_deliveries WHERE user_id=?",String.class,student.id()));work(education);assertEquals(1,count(learning,student,"DELIVERED"));}
 @Test void legacyWeeklyAlertChoiceIsPreservedForTheNewInbox(){var u=user(opp,"OPORTUNIDADES");opp.update("UPDATE app_users SET alert_preferences=? WHERE id=?","{\"enabled\":true,\"frequency\":\"weekly\",\"areas\":[\"technology\"]}",u.id());job();work(opportunities);assertEquals(0,count(opp,u,"DELIVERED"));assertEquals("DIGEST_SCHEDULED",opp.queryForObject("SELECT reason FROM communication_deliveries WHERE user_id=?",String.class,u.id()));}

 @Test void expiredSourceEventsNeverProduceFreshLookingNotifications(){var u=user(opp,"OPORTUNIDADES");long app=application(u);changeStage(app,"APPLIED");opp.update("UPDATE communication_events SET created_at=CURRENT_TIMESTAMP-INTERVAL '31 days' WHERE kind='APPLICATION_UPDATED' AND resource_id=? AND scope_id=?",app,u.id());work(opportunities);assertEquals(0,count(opp,u,"DELIVERED"));assertEquals(0,count(opp,u,"PENDING"));assertEquals("EXPIRED",opp.queryForObject("SELECT reason FROM communication_events WHERE kind='APPLICATION_UPDATED' AND resource_id=? AND scope_id=?",String.class,app,u.id()));}
 @Test void legacyAndNewReadPathsSerializeWithoutOppositeLockOrder()throws Exception{var c=course();var student=user(learning,"CAPACITA");long q=((Number)questions.create(student.email(),new QuestionService.QuestionInput(UUID.randomUUID(),c.id(),c.module(),c.lesson(),"Dúvida concorrente","Fixture",null,"","")).get("id")).longValue();questions.send(c.teacher().email(),q,new QuestionService.MessageInput(UUID.randomUUID(),"Resposta",null,"",""),true);var row=learning.queryForMap("SELECT id,legacy_id FROM communication_deliveries WHERE user_id=? AND status='DELIVERED'",student.id());long id=((Number)row.get("id")).longValue(),old=((Number)row.get("legacy_id")).longValue();try(var pool=Executors.newFixedThreadPool(4)){var futures=new ArrayList<Future<?>>();for(int i=0;i<12;i++){boolean direct=i%2==0;futures.add(pool.submit(()->{if(direct)education.read(student.email(),id);else legacy.read(student.email(),old);}));}for(var f:futures)f.get(15,TimeUnit.SECONDS);}assertEquals(0L,education.history(student.email(),Long.MAX_VALUE,20,false).get("unreadCount"));assertNotNull(learning.queryForObject("SELECT read_at FROM learning_notifications WHERE id=?",java.sql.Timestamp.class,old));}
}
